#!/usr/bin/env bashn# ==============================================================================n# pi-agent FULL VENDOR SYNC + MERGE PIPELINEn# Phase: Audit → Update → Sync → Build → Test → Commit → Push → Doc Update n# ==============================================================================nset -euo pipefailnnPROJECT_ROOT=~/projects/pi-agentnVENDOR_DIR=$PROJECT_ROOT/vendornLOG_FILE=/tmp/pi_vendor_sync_$(date +%s).lognexec > >(tee -a $LOG_FILE) 2>&1nn# ColorsnR='e[0;31m'; G='e[0;32m'; Y='e[1;33m'; C='e[0;36m'; NC='e[0m'nnlog()  { echo -e '${C}[SYNC]${NC} $*'; }nok()   { echo -e '${G}[OK]${NC} $*'; }nwarn() { echo -e '${Y}[WARN]${NC} $*'; }nerr()  { echo -e '${R}[ERR]${NC} $*'; }nncd $PROJECT_ROOT || { err 'Cannot cd to $PROJECT_ROOT'; exit 1; }n# ==============================================================================n# PHASE 0: Pre-flight — Git Safety Checkn# ============================================================================== nlog '=== PHASE 0: Git Safety Check ==='nn# Check for dirty treenDIRTY_COUNT=$(git status --short | wc -l)nif [ $DIRTY_COUNT -gt 0 ]; then n    warn 'Working tree has $DIRTY_COUNT uncommitted changes.'n    git add -An    git stash push -m 'auto-stash-before-vendor-sync-$(date +%Y%m%d-%H%M%S)'n    ok 'Stashed dirty work.'nelse n    ok 'Working tree clean.'nfi nn# Ensure we are on main branch nCURRENT_BRANCH=$(git branch --show-current)nif [ $CURRENT_BRANCH != 'main' ] && [ $CURRENT_BRANCH != 'master' ]; then n    warn 'Not on main/master (currently on $CURRENT_BRANCH). Checking out main...'n    git checkout main 2>/dev/null || git checkout master 2>/dev/null || { err 'No main/master branch'; exit 1; }nfi n# ==============================================================================n# PHASE 1: Vendor / Submodule Audit & Updaten# ============================================================================== nlog '=== PHASE 1: Vendor Audit & Update ==='nn# List of vendor submodules from .gitmodules nVENDORS=()nif [ -f .gitmodules ]; then n    while IFS= read -r line; do n        VENDORS+=( $line )n    done < <(grep -oP 'path = K+' .gitmodules | sed 's/path = //')nelse n    # Fallback hardcoded from fork-manifestn    VENDORS=(vendor/kimi-code-sovereign vendor/modelbeats vendor/oh-my-pi vendor/pi-subagents vendor/pi-upstream vendor/tinker-cookbook)nfi nlog 'Discovered vendors: ${VENDORS[*]}'nfor v in ${VENDORS[@]}; do n    if [ ! -d $v/.git ]; then n        warn '$v is not a git repo — initializing as submodule or skipping...'n        continue n    fi n    log 'Updating $v...'n    cd $vn    git fetch origin --quiet 2>/dev/null || { warn '  Could not fetch $v'; cd $PROJECT_ROOT; continue; }n    # Try to fast-forward to origin/main (or master)n    DEFAULT_BRANCH=$(git remote show origin 2>/dev/null | grep 'HEAD branch' | awk '{print $NF}' || echo 'main')n    git checkout $DEFAULT_BRANCH --quiet 2>/dev/null || git checkout origin/$DEFAULT_BRANCH --quiet 2>/dev/null || true n    git pull origin $DEFAULT_BRANCH --quiet 2>/dev/null || git reset --hard origin/$DEFAULT_BRANCH --quiet 2>/dev/null || true n    NEW_SHA=$(git rev-parse --short HEAD)n    cd $PROJECT_ROOTn    ok '  $v -> $NEW_SHA'n    # Stage the submodule pointer update n    git add $v || true ndonen# ==============================================================================n# PHASE 2: Identify & Sync Missing Internal Packages (oh-my-pi → packages)n# ============================================================================== nlog '=== PHASE 2: Sync oh-my-pi internal packages ==='nn# The oh-my-pi monorepo has packages/ that upstream now treats as internal deps.n# Your fork copied some (tui) but not the new ones (pi-utils, pi-natives).nOH_MY_PI=vendor/oh-my-pi/packagesnif [ -d $OH_MY_PI ]; then n    # Find every @oh-my-pi/* import in your fork n    MISSING_PKGS=()n    for imp in $(grep -roh '@oh-my-pi/[^'${NC}''${NC}']*' packages/ | sed 's/@oh-my-pi///' | sort -u); do n        PKG_NAME=$(echo $imp | cut -d/ -f1)n        if [ ! -d packages/$PKG_NAME ] && [ -d $OH_MY_PI/$PKG_NAME ]; then n            MISSING_PKGS+=( $PKG_NAME )n        fi n    done n    if [ ${#MISSING_PKGS[@]} -eq 0 ]; then n        ok 'No missing @oh-my-pi internal packages detected.'n    else n        warn 'Missing internal packages: ${MISSING_PKGS[*]}'n        for pkg in ${MISSING_PKGS[@]}; do n            log '  Syncing packages/$pkg from vendor...'n            # Use rsync to merge, preserving existing files in your fork n            rsync -av --ignore-existing $OH_MY_PI/$pkg/ packages/$pkg/ || cp -r $OH_MY_PI/$pkg packages/$pkg n            git add packages/$pkg || true n        done n        ok 'Synced ${#MISSING_PKGS[@]} missing internal packages.'n    fi n    # Also check for missing files inside EXISTING packages (like tui/deccara.ts)n    log 'Checking for missing files inside existing packages...'n    for idx in packages/*/src/index.ts; do n        [ -f $idx ] || continue n        pkg=$(echo $idx | cut -d/ -f2)n        # Only sync from vendor if the package exists there n        [ -d $OH_MY_PI/$pkg ] || continue n        grep -oE 'from './[^'${NC}']+' $idx 2>/dev/null | sed s/from './// | sed s/'// | while read rel; do n            fname=${rel}.ts n            if [ ! -f packages/$pkg/src/$fname ] && [ -f $OH_MY_PI/$pkg/src/$fname ]; then n                log '  Restoring packages/$pkg/src/$fname'n                cp $OH_MY_PI/$pkg/src/$fname packages/$pkg/src/$fname n                git add packages/$pkg/src/$fname || true n            fi n        done n    done nelse n    warn 'vendor/oh-my-pi/packages not found — skipping internal sync.'nfi n# ==============================================================================n# PHASE 3: Sync kimi-code-sovereign UI components (if referenced)n# ============================================================================== nlog '=== PHASE 3: Sync kimi-code-sovereign assets ==='nKIMI_UI=vendor/kimi-code-sovereignnif [ -d $KIMI_UI ]; then n    # If your fork references kimi-code UI assets, ensure they exist n    # (This is project-specific; add rules here if you have known sync paths)n    ok 'kimi-code-sovereign vendor present at $KIMI_UI'nelse n    warn 'kimi-code-sovereign vendor not found.'nfi n# ==============================================================================n# PHASE 4: Dependency Installation n# ============================================================================== nlog '=== PHASE 4: Install Dependencies ==='nnif [ -f bun.lockb ] || [ -f bun.lock ]; then n    log 'Detected bun project. Running bun install...'n    bun install || { err 'bun install failed'; exit 1; }nelif [ -f package-lock.json ]; then n    log 'Detected npm project. Running npm ci...'n    npm ci || { err 'npm ci failed'; exit 1; }nelse n    log 'No lockfile detected. Running bun install...'n    bun install || npm install || { err 'Package install failed'; exit 1; }nfi nok 'Dependencies installed.'n# ==============================================================================n# PHASE 5: Build & Type-Check n# ============================================================================== nlog '=== PHASE 5: Build & Type-Check ==='nn# Try to build the project nif [ -f package.json ]; then n    # Check for build script n    if grep -q 'build' package.json; then n        log 'Running build...'n        bun run build 2>&1 | tail -20 || npm run build 2>&1 | tail -20 || warn 'Build script failed or not found.'n    fi n    # Check for typecheck / lint n    if grep -q 'typecheck' package.json; then n        log 'Running typecheck...'n        bun run typecheck 2>&1 | tail -20 || warn 'Typecheck failed.'n    elif grep -q 'tsc' package.json; then n        log 'Running tsc...'n        bun run tsc --noEmit 2>&1 | tail -20 || warn 'tsc failed.'n    fi nfi n# ==============================================================================n# PHASE 6: Run Tests n# ============================================================================== nlog '=== PHASE 6: Run Tests ==='nnif [ -f package.json ] && grep -q 'test' package.json; then n    log 'Running test suite...'n    bun test 2>&1 | tail -30 || npm test 2>&1 | tail -30 || warn 'Tests failed or no test runner configured.'nelse n    warn 'No test script found in package.json — skipping tests.'nfi n# ==============================================================================n# PHASE 7: Commit Everything n# ============================================================================== nlog '=== PHASE 7: Commit ==='nn# Check if there is anything to commit nif git diff --cached --quiet && git diff --quiet; then n    ok 'No changes to commit. Everything is already in sync.'nelse n    git add -A n    git commit -m 'chore(vendor): full-grade sync of all upstream vendorsnnSyncs missing internal packages from oh-my-pi (pi-utils, pi-natives)nRestores missing TUI modules (deccara, kitty-graphics, etc.)nUpdates all vendor submodules to latest upstreamnRegenerates lockfile after vendor updatesnnRefs: vendor/oh-my-pi, vendor/kimi-code-sovereign, vendor/pi-upstream' || { err 'Commit failed'; exit 1; }n    ok 'Committed vendor sync.'nfi n# ==============================================================================n# PHASE 8: Push n# ============================================================================== nlog '=== PHASE 8: Push ==='nnif git remote get-url origin >/dev/null 2>&1; then n    git push origin $(git branch --show-current) || warn 'Push failed — may need manual auth or conflict resolution.'n    ok 'Pushed to origin.'nelse n    warn 'No origin remote configured — skipping push.'nfi n# ==============================================================================n# PHASE 9: Update README / FORK_MANIFEST n# ============================================================================== nlog '=== PHASE 9: Update Documentation ==='nn# Update FORK_MANIFEST.md or README.md with current sync date nfor doc in FORK_MANIFEST.md README.md; do n    if [ -f $doc ]; then n        sed -i '1s/^/# $doc — Last Vendor Sync: $(date -Iseconds)n/' $doc 2>/dev/null || true n        git add $doc || true n    fi ndonen# If we have the fork-manifest generator script, run it nif [ -f packages/fork-manifest/gen.ts ]; then n    log 'Regenerating fork-manifest.json...'n    bun run packages/fork-manifest/gen.ts 2>/dev/null || npx tsx packages/fork-manifest/gen.ts 2>/dev/null || warn 'Could not regenerate fork-manifest.'n    git add fork-manifest.json 2>/dev/null || true nfi n# Amend the commit with doc updates if there are any nif ! git diff --cached --quiet; then n    git commit --amend --no-edit || true n    ok 'Amended commit with documentation updates.'nfi n# ==============================================================================n# DONE n# ============================================================================== nlog '=== SYNC COMPLETE ==='nok 'Log saved to: $LOG_FILE'nok 'Next steps:'necho '  1. Review the commit: git show --stat HEAD'necho '  2. Run pi: pi'necho '  3. If pi still fails, paste the NEW error here.'n